-- Local isolated Postgres or an explicit rollback verification. Never commit fixtures.
begin;
do $test$
declare uid uuid:=gen_random_uuid();other_uid uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();other_sid uuid:=gen_random_uuid();rid uuid:=gen_random_uuid();
 p1 uuid:=gen_random_uuid();p2 uuid:=gen_random_uuid();v1 uuid:=gen_random_uuid();v2 uuid:=gen_random_uuid();fileid uuid;orderid uuid;bid bigint;roomid bigint;
 starts date:=(now() at time zone 'America/Bahia')::date+600;payload jsonb;q jsonb;result jsonb;upload jsonb;stock_before integer;revision integer;
begin
 insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values(uid,'authenticated','authenticated',uid||'@example.invalid',now(),'{}','{}',now(),now()),(other_uid,'authenticated','authenticated',other_uid||'@example.invalid',now(),'{}','{}',now(),now());
 insert into auth.identities(provider_id,user_id,identity_data,provider) values(uid::text,uid,jsonb_build_object('sub',uid),'google'),(other_uid::text,other_uid,jsonb_build_object('sub',other_uid),'google');
 insert into auth.sessions(id,user_id,created_at,updated_at) values(sid,uid,now(),now()),(other_sid,other_uid,now(),now());
 insert into lotus_private.admin_users(user_id) values(uid);
 insert into lotus_private.rooms(name,type,capacity,price,active,floor) values('__romance_test_'||uid,'casal',3,10000,1,'terreo') returning id into roomid;
 insert into lotus_private.occupancy_rates(floor,guests,amount) values('terreo',1,10000),('terreo',2,20000) on conflict(floor,guests) where start is null do update set amount=excluded.amount,example=false;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid)::text,true);
 result:=public.lotus_romance_api('admin_save',jsonb_build_object('id',p1,'name','Synthetic wine','category','brindes','description','Test only','photo','/img casal/casal.jpg','active',true,'max_quantity',2,'photos_required',0,'exclusive_group','','position',1,'variants',jsonb_build_array(jsonb_build_object('id',v1,'name','Brut','price',1000,'stock',1,'active',true))));
 result:=public.lotus_romance_api('admin_save',jsonb_build_object('id',p2,'name','Synthetic frame','category','lembrancas','photo','/img casal/casal.jpg','active',true,'max_quantity',2,'photos_required',1,'position',2,'variants',jsonb_build_array(jsonb_build_object('id',v2,'name','One photo','price',500,'stock',2,'active',true))));
 assert jsonb_array_length(public.lotus_romance_api('catalog')->'products')=2;
 payload:=jsonb_build_object('start',starts,'end',starts+1,'category_slug','duplo','floor','terreo','preference','sem_preferencia','guests',2,'party',jsonb_build_array(jsonb_build_object('adults',1,'children_ages',jsonb_build_array(5))),'items',jsonb_build_array(jsonb_build_object('variant_id',v1,'quantity',1),jsonb_build_object('variant_id',v2,'quantity',1)),'request_id',rid,'guest','Synthetic guest','phone','73999999999','privacy_accepted',true,'instructions','Test instructions');
 q:=public.lotus_romance_api('quote',payload);assert (q->>'stay_total')::bigint=10000 and (q->>'decoration_total')::bigint=1500 and (q->>'total')::bigint=11500 and (q->>'photos_required')::integer=1,'Authoritative pricing and free child capacity';
 begin perform public.lotus_romance_api('quote',payload||jsonb_build_object('items',jsonb_build_array(jsonb_build_object('variant_id',v1,'quantity',2))));raise exception 'Insufficient stock accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.lotus_romance_api('quote',payload||jsonb_build_object('items',jsonb_build_array(jsonb_build_object('variant_id',v1,'quantity',1),jsonb_build_object('variant_id',v1,'quantity',1))));raise exception 'Duplicate variant accepted';exception when sqlstate 'PT400' then null;end;
 upload:=public.lotus_romance_api('upload_register',jsonb_build_object('request_id',rid,'extension','png'));fileid:=(upload->>'id')::uuid;
 payload:=payload||jsonb_build_object('photos',jsonb_build_array(fileid),'expected_total',11500,'expected_items',q->'items','payment_status','paid','status','confirmada');
 begin perform public.lotus_romance_api('book',payload);raise exception 'Missing file accepted';exception when sqlstate 'PT400' then null;end;
 insert into storage.objects(bucket_id,name,owner,metadata) values('lotus-romance-private',upload->>'path',uid,'{"size":1000,"mimetype":"image/png"}');
 begin perform public.lotus_romance_api('book',payload||'{"expected_total":1}');raise exception 'Tampered total accepted';exception when sqlstate 'PT409' then null;end;
 assert not exists(select 1 from lotus_private.romance_orders),'Failure creates no partial order';
 begin perform public.lotus_romance_api('book',payload||'{"privacy_accepted":false}');raise exception 'Missing consent accepted';exception when sqlstate 'PT400' then null;end;
 result:=public.lotus_romance_api('book',payload);orderid:=(result->>'id')::uuid;bid:=(result->>'booking_id')::bigint;
 assert (select total=11500 and status='pendente' and not room_assigned and guests=2 and paying_guests=1 from lotus_private.bookings where id=bid),'One pending stock hold and grand total';
 assert exists(select 1 from lotus_private.booking_guest_links where booking_id=bid and user_id=uid),'Automatic Google link';
 assert (select stock=0 from lotus_private.romance_variants where id=v1);
 assert (select order_id=orderid from lotus_private.romance_uploads where id=fileid);
 result:=public.lotus_romance_api('book',payload);assert (result->>'replayed')::boolean and (select count(*)=1 from lotus_private.romance_orders),'Retry idempotency';
 begin perform public.lotus_romance_api('book',payload||'{"phone":"73888888888"}');raise exception 'Changed replay accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.lotus_romance_api('quote',payload);raise exception 'Overlapping stock accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.lotus_romance_api('upload_remove',jsonb_build_object('id',fileid));raise exception 'Finalized photo deleted';exception when sqlstate 'PT404' then null;end;
 begin perform public.lotus_romance_api('admin_status',jsonb_build_object('id',orderid,'revision',1,'operational','preparado'));raise exception 'Prepared unconfirmed booking';exception when sqlstate 'PT409' then null;end;
 result:=public.lotus_assignment_api(jsonb_build_object('booking_id',bid,'room_id',roomid));
 result:=public.lotus_api('booking_status',jsonb_build_object('id',bid,'status','confirmada'));
 result:=public.lotus_romance_api('admin_status',jsonb_build_object('id',orderid,'revision',1,'operational','em_preparacao','external_reference','manual-test'));
 result:=public.lotus_romance_api('admin_orders');assert result->'orders'->0->>'financial'='aguardando','Preparation does not invent payment';
 insert into lotus_private.receipts(id,booking_id,amount,received_on,method,created_by) values(gen_random_uuid(),bid,5000,(now() at time zone 'America/Bahia')::date,'pix',uid);
 result:=public.lotus_romance_api('admin_orders');assert result->'orders'->0->>'financial'='parcial';
 update lotus_private.romance_variants set price=99999 where id=v1;
 assert (select items->0->>'unit_price'='1000' from lotus_private.romance_orders where id=orderid),'Immutable historical pricing';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_uid,'role','authenticated','session_id',other_sid)::text,true);
 assert jsonb_array_length(public.lotus_romance_api('mine')->'orders')=0,'Other guest cannot read order';
 begin perform public.lotus_romance_api('file_access',jsonb_build_object('id',fileid));raise exception 'Other guest accessed photo';exception when sqlstate 'PT404' then null;end;
 begin perform public.lotus_romance_api('admin_orders');raise exception 'Guest accessed admin';exception when sqlstate 'PT401' then null;end;
 perform set_config('romance.test.other',other_uid::text,true);perform set_config('romance.test.other_session',other_sid::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid)::text,true);
 result:=public.lotus_api('booking_status',jsonb_build_object('id',bid,'status','cancelada'));
 assert (select operational='cancelado' from lotus_private.romance_orders where id=orderid);
 assert (select stock=1 from lotus_private.romance_variants where id=v1),'Cancellation restores stock once';
 update lotus_private.bookings set status='cancelada' where id=bid;
 assert (select stock=1 from lotus_private.romance_variants where id=v1),'Repeated cancellation does not duplicate stock';
 result:=public.lotus_romance_api('admin_purge_paths',jsonb_build_object('id',orderid));
 assert jsonb_array_length(result->'paths')=1,'Completed/cancelled personal photos can be purged';
 begin perform public.lotus_romance_api('admin_purge_finish',jsonb_build_object('id',orderid));raise exception 'Purge metadata removed before object';exception when sqlstate 'PT409' then null;end;
 assert lotus_private.romance_can_purge(upload->>'path'),'Live admin may remove cancelled personal photo';
 execute 'set local role authenticated';
 delete from storage.objects where bucket_id='lotus-romance-private' and name=upload->>'path';
 execute 'reset role';
 assert not exists(select 1 from storage.objects where bucket_id='lotus-romance-private' and name=upload->>'path'),'Storage DELETE policy permits authorized retention';
 result:=public.lotus_romance_api('admin_purge_finish',jsonb_build_object('id',orderid));
 assert not exists(select 1 from lotus_private.romance_uploads where id=fileid),'Personal photo metadata purged';
 assert (select total=11500 and jsonb_array_length(items)=2 from lotus_private.romance_orders where id=orderid),'Purge preserves financial history';
 begin perform public.lotus_romance_api('file_access',jsonb_build_object('id',fileid));raise exception 'Purged file accessible';exception when sqlstate 'PT404' then null;end;
 delete from auth.sessions where id=sid;
 begin perform public.lotus_romance_api('mine');raise exception 'Revoked session accepted';exception when sqlstate 'PT401' then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_uid,'role','authenticated','session_id',other_sid)::text,true);
end $test$;
set local role authenticated;
do $test$ begin
 assert (select count(*)=0 from storage.objects where bucket_id='lotus-romance-private'),'Private Storage RLS isolates users';
 begin perform 1 from lotus_private.romance_orders;raise exception 'Direct private order access allowed';exception when insufficient_privilege then null;end;
 begin perform lotus_private.romance_quote('{}');raise exception 'Direct privileged helper access allowed';exception when insufficient_privilege then null;end;
end $test$;
reset role;
rollback;
